components.css:
.ds-btn { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 600; min-height: 2.75rem; padding: 0.75rem 1rem; border-radius: 0; background: transparent; border: 1px solid; cursor: pointer; transition: border-color 150ms, background-color 150ms, color 150ms; }
.ds-btn:focus-visible { outline: 2px solid var(--color-live, #cb2928); outline-offset: 2px; }
.ds-btn-live { color: var(--color-live, #cb2928); border-color: color-mix(in oklab, var(--color-live, #cb2928) 60%, transparent); }
.ds-btn-live:hover { border-color: var(--color-live, #cb2928); }
.ds-btn-live:active { background-color: color-mix(in oklab, var(--color-live, #cb2928) 8%, transparent); }
.ds-btn-live[aria-busy="true"] { opacity: 0.6; cursor: progress; }

.ds-btn { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 600; min-height: 2.75rem; padding: 0.75rem 1rem; border-radius: 0; background: transparent; border: 1px solid; cursor: pointer; transition: border-color 150ms, background-color 150ms; }
.ds-btn:focus-visible { outline: 2px solid var(--color-live, #cb2928); outline-offset: 2px; }
.ds-btn-ink { color: var(--color-ink, #1b2025); border-color: color-mix(in oklab, var(--color-ink, #1b2025) 35%, transparent); }
.ds-btn-ink:hover { border-color: color-mix(in oklab, var(--color-ink, #1b2025) 80%, transparent); }
.ds-btn-ink:active { background-color: color-mix(in oklab, var(--color-ink, #1b2025) 5%, transparent); }

.ds-field { display: flex; flex-direction: column; gap: 0.375rem; }
.ds-field-label { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.06em; text-transform: uppercase; font-weight: 400; color: var(--color-ink-soft, #565b61); }
.ds-input { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 1rem; min-height: 2.75rem; width: 100%; padding: 0.5rem 0.25rem; background: transparent; color: var(--color-ink, #1b2025); border: 0; border-bottom: 1px solid color-mix(in oklab, var(--color-ink, #1b2025) 30%, transparent); border-radius: 0; caret-color: var(--color-live, #cb2928); }
.ds-input::placeholder { color: var(--color-ink-faint, #63676c); }
.ds-input:focus { border-bottom-color: var(--color-live, #cb2928); outline: none; }

.ds-bank-framed { display: flex; flex-direction: column; gap: 0.75rem; padding: 1rem; border: 1px solid var(--color-rule-strong, #686e72); border-radius: 0; background: var(--color-stock-deep, #dde0e3); color: var(--color-ink, #1b2025); }
.ds-bank-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; }
.ds-slot-label { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 500; color: var(--color-ink-soft, #565b61); margin: 0; }
.ds-bank-body { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 1rem; line-height: 1.5rem; margin: 0; color: var(--color-ink, #1b2025); }

.ds-slots { display: flex; flex-direction: column; list-style: none; margin: 0; padding: 0; border-bottom: 1px solid var(--color-rule-strong, #686e72); }
.ds-slot { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 0.25rem 1rem; padding: 0.75rem; border-radius: 0; }
.ds-slot-waiting { border-top: 1px dashed var(--color-rule, #808589); padding-top: 0.5rem; padding-bottom: 0.5rem; }
.ds-slot-filled { border-top: 1px solid var(--color-rule-strong, #686e72); }
.ds-slot-live { border-top: 2px solid var(--color-live, #cb2928); background-color: var(--color-live-sunk, #ffd9d3); }
.ds-card-name { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 1rem; line-height: 1.5rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-ink, #1b2025); }
.ds-slot-label { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 500; color: var(--color-ink-soft, #565b61); }
.ds-slot-num { color: var(--color-ink-faint, #63676c); }

.ds-season-control { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 0.75rem; }
@media (max-width: 639px) { .ds-season-control { grid-template-columns: 1fr; } }
.ds-season-control button { min-height: 2.75rem; border: 1px solid var(--color-ink, #1b2025); border-radius: 0; background: transparent; color: var(--color-ink, #1b2025); }

.ds-patch { display: inline-flex; align-items: baseline; gap: 0.25rem; padding: 0.25rem 0.5rem; border: 1px solid; border-radius: 0; font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; }
.ds-patch-g { color: var(--color-pos-g, #2e6c8d); border-color: color-mix(in oklab, var(--color-pos-g, #2e6c8d) 55%, transparent); background-color: color-mix(in oklab, var(--color-pos-g, #2e6c8d) 10%, transparent); }
.ds-patch-f { color: var(--color-pos-f, #586e3b); border-color: color-mix(in oklab, var(--color-pos-f, #586e3b) 55%, transparent); background-color: color-mix(in oklab, var(--color-pos-f, #586e3b) 10%, transparent); }
.ds-patch-c { color: var(--color-pos-c, #71568f); border-color: color-mix(in oklab, var(--color-pos-c, #71568f) 55%, transparent); background-color: color-mix(in oklab, var(--color-pos-c, #71568f) 10%, transparent); }

.ds-correction { display: flex; flex-direction: column; gap: 0.25rem; padding: 0.75rem; border-top: 2px solid var(--color-ink, #1b2025); border-radius: 0; }
.ds-slot-label { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 500; color: var(--color-ink-soft, #565b61); }
.ds-correction-body { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.875rem; line-height: 1.25rem; margin: 0; color: var(--color-ink, #1b2025); }

.ds-rail { border-bottom: 1px solid color-mix(in oklab, var(--color-rail, #556c80) 40%, transparent); }
.ds-rail-inner { display: flex; align-items: baseline; justify-content: space-between; gap: 0.75rem; max-width: 48rem; margin: 0 auto; padding: 1rem 1.25rem; }
.ds-rail-left { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 0.75rem; }
.ds-wordmark { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 1rem; line-height: 1.5rem; font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; color: var(--color-ink, #1b2025); white-space: nowrap; }
.ds-slot-label { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 500; color: var(--color-ink-soft, #565b61); white-space: nowrap; }
.ds-rail-action { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 500; color: var(--color-ink-soft, #565b61); text-decoration: none; transition: color 150ms; }
.ds-rail-action:hover { color: var(--color-ink, #1b2025); }
.ds-rail-action:focus-visible { outline: 2px solid var(--color-live, #cb2928); outline-offset: 2px; }

.ds-bank { display: flex; flex-direction: column; gap: 0.75rem; }
.ds-bank-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; }
.ds-slot-label { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 500; color: var(--color-ink-soft, #565b61); margin: 0; }
.ds-bank-body { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 1rem; line-height: 1.5rem; margin: 0; color: var(--color-ink, #1b2025); }

.ds-plan { display: flex; flex-direction: column; gap: 0.5rem; }
.ds-plan-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; }
.ds-slot-label { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); font-size: 0.6875rem; line-height: 1rem; letter-spacing: 0.14em; text-transform: uppercase; font-weight: 500; color: var(--color-ink-soft, #565b61); margin: 0; }
.ds-plan-grid { display: flex; flex-direction: column; border-top: 1px solid var(--color-rule-strong, #686e72); }
.ds-plan-row { display: flex; align-items: stretch; gap: 0.5rem; }
.ds-plan-no { font-family: var(--font-sans, "Archivo", ui-sans-serif, system-ui, sans-serif); width: 1.5rem; flex-shrink: 0; padding-top: 0.125rem; text-align: right; font-size: 0.6875rem; line-height: 1rem; font-variant-numeric: tabular-nums; color: var(--color-ink-faint, #63676c); }
.ds-plan-cells { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); flex: 1; border-left: 1px solid var(--color-rule-strong, #686e72); }
.ds-plan-cell { height: 1.25rem; border-right: 1px dashed var(--color-rule, #808589); border-bottom: 1px dashed var(--color-rule, #808589); }
.ds-plan-cell-last { border-bottom-style: solid; border-bottom-color: var(--color-rule-strong, #686e72); }
